// Generates the sign-in theme's component styles from the console kit's own
// style constants, so the kit is the one source for both surfaces
// (geekdojo/geekdojo-brain#988, ui.md §4.2, ARCH-DRY). The output,
// src/login/resources/css/components.css, is committed; test/styles.test.ts
// fails until it is regenerated after a kit constant changes.
//
//   npm run identity-theme:styles      (rewrites components.css)
//
// Every colour the kit uses is a var(--rasp-*) token from ui/styles/tokens.css,
// so the generated file carries no colour of its own (F-988-12).
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import type { CSSProperties } from 'react';
import { BTN_COLORS, btnStyle, fieldStyle, hintStyle, sectionLabelStyle, type BtnVariant } from '../components/kit';

/** components.css, under ui/ (this file runs from .test-out/identity-theme). */
export const COMPONENTS_CSS = path.join('identity-theme', 'src', 'login', 'resources', 'css', 'components.css');

// React's unitless properties among those the kit sets.
const UNITLESS = new Set(['opacity', 'lineHeight', 'fontWeight', 'zIndex', 'flex', 'flexGrow', 'flexShrink', 'order']);

function kebab(prop: string): string {
  return prop.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
}

function value(prop: string, v: unknown): string {
  if (typeof v === 'number' && !UNITLESS.has(prop) && v !== 0) return `${v}px`;
  return String(v);
}

/** One CSS rule from a React style object, in the object's key order. */
export function rule(selector: string, style: CSSProperties): string {
  const decls = Object.entries(style)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => `  ${kebab(k)}: ${value(k, v)};`);
  return `${selector} {\n${decls.join('\n')}\n}\n`;
}

/** The properties of b that differ from a. */
function diff(a: CSSProperties, b: CSSProperties): CSSProperties {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(b)) {
    if ((a as Record<string, unknown>)[k] !== v) out[k] = v;
  }
  return out as CSSProperties;
}

const VARIANTS: BtnVariant[] = ['primary', 'danger', 'ghost'];

/** The whole of components.css. */
export function generate(): string {
  const base = btnStyle('default', false, false, false);
  const parts = [
    '/* GENERATED by ui/identity-theme/styles.ts from ui/components/kit.tsx. Do not edit:\n' +
      '   change the kit, then run `npm run identity-theme:styles` (geekdojo/geekdojo-brain#988). */\n',
    rule('.rasp-btn', base),
    rule('.rasp-btn:hover:not(:disabled)', { background: BTN_COLORS.default.hover }),
    rule('.rasp-btn:disabled', diff(base, btnStyle('default', false, false, true))),
    rule('.rasp-btn-default', { border: `1px solid ${BTN_COLORS.default.border}`, background: BTN_COLORS.default.bg, color: BTN_COLORS.default.text }),
    rule('.rasp-btn-default:hover:not(:disabled)', { background: BTN_COLORS.default.hover }),
  ];
  for (const v of VARIANTS) {
    const c = BTN_COLORS[v];
    parts.push(rule(`.rasp-btn-${v}`, { border: `1px solid ${c.border}`, background: c.bg, color: c.text }));
    parts.push(rule(`.rasp-btn-${v}:hover:not(:disabled)`, { background: c.hover }));
  }
  parts.push(rule('.rasp-field', fieldStyle));
  parts.push(rule('.rasp-section-label', sectionLabelStyle));
  parts.push(rule('.rasp-hint', hintStyle));
  return parts.join('\n');
}

if (require.main === module) {
  // Run from ui/ (npm run identity-theme:styles).
  writeFileSync(path.join(process.cwd(), COMPONENTS_CSS), generate());
  process.stdout.write(`wrote ${COMPONENTS_CSS}\n`);
}
